  ('69462bb97b78013c4213b5af', '69462bb97b78013c4213b5a9', NULL, 'NightOwl', 'Mountain View', 'Slept right through it apparently!', 0, NULL, 2, 1765870645371, NULL, 0),
  ('69462bb97b78013c4213b5b0', '69462bb97b78013c4213b5a9', NULL, 'WFHLife', 'Pleasanton', 'Just a tiny wobble here. Nothing fell off the shelves.', 1, 3, 1, 1765870800256, NULL, 0),
  ('69462bb97b78013c4213b5b2', '69462bb97b78013c4213b5b1', NULL, 'EastBayMom', 'Dublin', 'With all the recent activity, I want to make sure my family is prepared. What emergency kits do you all recommend? Looking for something comprehensive but not too expensive. We have 2 kids (ages 5 and 8) and a dog.', NULL, NULL, 26, 1764656440603, NULL, 1),
  ('69462bb97b78013c4213b5b3', '69462bb97b78013c4213b5b1', NULL, 'BayNative', 'Pleasanton', 'We got the Ready America kit from Amazon. It has supplies for 4 people for 72 hours. Added extra water and dog food separately.', NULL, NULL, 11, 1764830091182, NULL, 0),
  ('69462bb97b78013c4213b5b4', '69462bb97b78013c4213b5b1', NULL, 'HikingEnthusiast', 'San Ramon', 'Don''t forget medications! We keep a 2-week supply of all prescriptions in our go-bag.', NULL, NULL, 1, 1764956474006, NULL, 0),
  ('69462bb97b78013c4213b5b5', '69462bb97b78013c4213b5b1', NULL, 'FamilyFirst', 'Oakland', 'I''d recommend building your own kit. The pre-made ones often have cheap quality items. Start with water (1 gallon per person per day), first aid, flashlights, and go from there.', NULL, NULL, 4, 1765164752085, NULL, 0),
  ('69462bb97b78013c4213b5b6', '69462bb97b78013c4213b5b1', NULL, 'BikeCommuter', 'Dublin', 'We did a combo - bought a basic kit then added personal items. Don''t forget important documents (copies of IDs, insurance papers) in a waterproof bag!', NULL, NULL, 11, 1765286689332, NULL, 0),
  ('69462bb97b78013c4213b5b7', '69462bb97b78013c4213b5b1', NULL, 'StartupLife', 'Livermore', 'Just went through our kit after the swarm started. Half the food was expired! Set a calendar reminder to check it every 6 months.', NULL, NULL, 1, 1765452424561, NULL, 0),
  ('69462bba7b78013c4213b5b9', '69462bba7b78013c4213b5b8', NULL, 'BayAreaResident', 'Pleasanton', 'I''m trying to learn more about the fault system under San Ramon/Dublin area. Can anyone recommend good resources or explain why we''re seeing so much activity lately? I''m fascinated by the geology here.', NULL, NULL, 34, 1764276251071, NULL, 1),
  ('69462bba7b78013c4213b5ba', '69462bba7b78013c4213b5b8', NULL, 'TechWorker', 'Berkeley', 'USGS has great resources! The Calaveras Fault is actually one of the most active in the Bay Area. It runs from Hollister up through the East Bay.', NULL, NULL, 10, 1764385759498, NULL, 0),
  ('69462bba7b78013c4213b5bb', '69462bba7b78013c4213b5b8', NULL, 'BayNative', 'Hayward', 'Check out the earthquake.usgs.gov site. They have detailed maps showing all the fault lines. The recent swarm is pretty typical for Calaveras - it has these episodes regularly.', NULL, NULL, 10, 1764386148415, NULL, 0),
  ('69462bba7b78013c4213b5bc', '69462bba7b78013c4213b5b8', NULL, 'BookLover', 'Berkeley', 'I''m a geology grad student at Cal. The Calaveras is what we call a ''creeping'' fault - it moves slowly and constantly rather than in big sudden jolts. That''s why we get lots of small quakes.', NULL, NULL, 4, 1764500235809, NULL, 0),
  ('69462bba7b78013c4213b5bd', '69462bba7b78013c4213b5b8', NULL, 'OldTimer', 'Oakland', 'The Hayward Fault is the one that really worries seismologists. It''s ''locked'' and building up stress. The Calaveras activity doesn''t really affect it though - they''re separate systems.', NULL, NULL, 0, 1764698394956, NULL, 0),
  ('69462bba7b78013c4213b5bf', '69462bba7b78013c4213b5be', NULL, 'ApartmentDweller', 'Fremont', 'My dog has been super restless the past week and seems to know when a quake is coming. About 30 seconds before the last one, she started whining and hid under the bed. Anyone else notice this with their pets?', NULL, NULL, 25, 1766013286053, NULL, 1),
  ('69462bba7b78013c4213b5c0', '69462bba7b78013c4213b5be', NULL, 'DogWalker', 'San Jose', 'Yes! My cat always runs and hides about a minute before I feel anything. It''s actually how I know to brace myself now 😂', NULL, NULL, 0, 1766146974557, NULL, 0),
  ('69462bba7b78013c4213b5c2', '69462bba7b78013c4213b5c1', NULL, 'WFHLife', 'Cupertino', 'My 4-year-old has been asking a lot of questions after feeling some of the recent quakes. How do you all talk to your little ones about earthquakes without scaring them? Looking for age-appropriate ways to explain it.', NULL, NULL, 33, 1764942641057, NULL, 1),
  ('69462bba7b78013c4213b5c3', '69462bba7b78013c4213b5c1', NULL, 'RunnerLife', 'Dublin', 'We told our daughter that the Earth is like a big puzzle, and sometimes the pieces wiggle a little bit. She thought that was cool rather than scary!', NULL, NULL, 2, 1765089739152, NULL, 0),
  ('69462bba7b78013c4213b5c4', '69462bba7b78013c4213b5c1', NULL, 'HomeOwner2020', 'San Ramon', 'There are some great kids'' books about earthquakes. ''Earthquake!'' by Mia Posada is good for that age. Makes it educational rather than frightening.', NULL, NULL, 4, 1765176111844, NULL, 0),
  ('69462bba7b78013c4213b5c5', '69462bba7b78013c4213b5c1', NULL, 'BookLover', 'Pleasanton', 'We made it into a game - practiced ''drop, cover, hold on'' like a fun drill. Now my son thinks he''s a superhero earthquake responder 😊', NULL, NULL, 5, 1765350213692, NULL, 0),
  ('69462bba7b78013c4213b5c6', '69462bba7b78013c4213b5c1', NULL, 'PetParent', 'Danville', 'Our school had an earthquake drill and the teacher explained it really well. Maybe check what resources your kid''s preschool has?', NULL, NULL, 12, 1765563169652, NULL, 0),
  ('69462bba7b78013c4213b5c8', '69462bba7b78013c4213b5c7', NULL, 'DogWalker', 'Cupertino', 'I''m renting an older apartment building in Oakland (built in 1960s). After all this earthquake activity, I''m wondering if my building is safe. How do I find out if it''s been retrofitted? Anyone know what to look for?', NULL, NULL, 29, 1765461387024, NULL, 1),
  ('69462bba7b78013c4213b5c9', '69462bba7b78013c4213b5c7', NULL, 'WFHLife', 'Oakland', 'Oakland has a soft-story retrofit ordinance. You can check the city''s website for a list of buildings that have completed retrofitting. If yours is on the ''not yet compliant'' list, that''s concerning.', NULL, NULL, 2, 1765532641057, NULL, 0),
  ('69462bba7b78013c4213b5ca', '69462bba7b78013c4213b5c7', NULL, 'BayAreaResident', 'Berkeley', 'Look for the building permit history - you can usually find this online through the city. Retrofit work would show up there.', NULL, NULL, 8, 1765770567452, NULL, 0),
  ('69462bba7b78013c4213b5cb', '69462bba7b78013c4213b5c7', NULL, 'NewToArea', 'San Francisco', 'Ask your landlord directly! They''re required to disclose certain information. If they''re evasive, that''s a red flag.', NULL, NULL, 12, 1765927466019, NULL, 0),
  ('69462bba7b78013c4213b5cc', '69462bba7b78013c4213b5c7', NULL, 'EarlyBird', 'Hayward', 'Soft-story buildings (the ones with parking on the ground floor and apartments above) are the biggest concern. If that''s your building type, definitely investigate.', NULL, NULL, 7, 1766148942689, NULL, 0),
  ('69462bba7b78013c4213b5ce', '69462bba7b78013c4213b5cd', NULL, 'Foodie925', 'El Cerrito', 'If the big one hits and cell towers go down, how are you planning to reach your family? We''re scattered across the Bay Area during work/school hours. Looking for ideas on emergency communication plans.', NULL, NULL, 33, 1765116544941, NULL, 1),
  ('69462bba7b78013c4213b5cf', '69462bba7b78013c4213b5cd', NULL, 'Concerned_Citizen', 'San Jose', 'We have an out-of-state contact that everyone knows to call/text. Sometimes long-distance calls work when local ones don''t. My sister in Texas is our check-in point.', NULL, NULL, 1, 1765190317651, NULL, 0),
  ('69462bba7b78013c4213b5d0', '69462bba7b78013c4213b5cd', NULL, 'GardenGuru', 'Fremont', 'Texts often work when calls don''t - they use less bandwidth. We have a family group chat and everyone knows to send their status there first.', NULL, NULL, 1, 1765377119208, NULL, 0),
  ('69462bba7b78013c4213b5d1', '69462bba7b78013c4213b5cd', NULL, 'PetParent', 'Walnut Creek', 'We designated physical meetup points - one near each kid''s school and one at home. If we can''t communicate, we know where to find each other.', NULL, NULL, 9, 1765434247397, NULL, 0),
  ('69462bba7b78013c4213b5d2', '69462bba7b78013c4213b5cd', NULL, 'SafetyFirst', 'Concord', 'Got a pair of two-way radios. Good range for our area. Also useful for camping!', NULL, NULL, 8, 1765608514648, NULL, 0),
  ('69462bbb7b78013c4213b5d3', '69462bba7b78013c4213b5cd', NULL, 'BayNative', 'San Ramon', 'The Red Cross has a ''Safe and Well'' website where you can register/search for loved ones after a disaster. Bookmark it!', NULL, NULL, 9, 1765618620375, NULL, 0),
  ('69462bbb7b78013c4213b5d5', '69462bbb7b78013c4213b5d4', NULL, 'OldTimer', 'San Ramon', 'Been a wild couple of weeks with all these quakes centered right under us. How''s everyone holding up? Any damage reports or just the usual shaking? My kids are getting jumpy every time the house creaks now.', NULL, NULL, 11, 1765217581686, NULL, 1),
  ('69462bbb7b78013c4213b5d6', '69462bbb7b78013c4213b5d4', NULL, 'RunnerLife', 'Pleasanton', 'Thanks for starting this thread! It''s nice to know neighbors are looking out for each other.', NULL, NULL, 7, 1765229596406, NULL, 0),
  ('69462bbb7b78013c4213b5d7', '69462bbb7b78013c4213b5d4', NULL, 'StartupLife', 'Dublin', 'We''re hanging in there. The constant small quakes are unnerving but no damage here thankfully.', NULL, NULL, 3, 1765314895661, NULL, 0),
  ('69462bbb7b78013c4213b5d8', '69462bbb7b78013c4213b5d4', NULL, 'Concerned_Citizen', 'San Jose', 'Great idea! Would definitely join a meetup. Safety in community!', NULL, NULL, 1, 1765317194038, NULL, 0),
  ('69462bbb7b78013c4213b5da', '69462bbb7b78013c4213b5d9', NULL, 'OldTimer', 'Dublin', 'With all the new development happening in Dublin and the ongoing earthquake swarm, I''m curious if anyone knows how the new buildings are being designed for seismic safety. Seems like important info given our location on the fault.', NULL, NULL, 8, 1765730510849, NULL, 1),
  ('69462bbb7b78013c4213b5db', '69462bbb7b78013c4213b5d9', NULL, 'RunnerLife', 'Berkeley', 'Thanks for starting this thread! It''s nice to know neighbors are looking out for each other.', NULL, NULL, 2, 1765738087284, NULL, 0),
  ('69462bbb7b78013c4213b5dc', '69462bbb7b78013c4213b5d9', NULL, 'QuakeWatcher', 'Berkeley', 'We''re hanging in there. The constant small quakes are unnerving but no damage here thankfully.', NULL, NULL, 0, 1765773870687, NULL, 0),
  ('69462bbb7b78013c4213b5dd', '69462bbb7b78013c4213b5d9', NULL, 'Foodie925', 'Oakland', 'Great idea! Would definitely join a meetup. Safety in community!', NULL, NULL, 1, 1765776240755, NULL, 0),
  ('69462bbb7b78013c4213b5df', '69462bbb7b78013c4213b5de', NULL, 'CommutingPro', 'Danville', 'Would anyone be interested in an informal meetup to discuss earthquake preparedness? We could share tips, maybe do a neighborhood walk to identify safe spots and hazards. I''m in the Danville/San Ramon area but happy to meet anywhere accessible.', NULL, NULL, 12, 1765114860076, NULL, 1),
  ('69462bbb7b78013c4213b5e0', '69462bbb7b78013c4213b5de', NULL, 'TechBro', 'Pleasanton', 'Thanks for starting this thread! It''s nice to know neighbors are looking out for each other.', NULL, NULL, 0, 1765184445846, NULL, 0),
  ('69462bbb7b78013c4213b5e1', '69462bbb7b78013c4213b5de', NULL, 'BookLover', 'Livermore', 'We''re hanging in there. The constant small quakes are unnerving but no damage here thankfully.', NULL, NULL, 6, 1765249964800, NULL, 0),
  ('69462bbb7b78013c4213b5e2', '69462bbb7b78013c4213b5de', NULL, 'Foodie925', 'Danville', 'Great idea! Would definitely join a meetup. Safety in community!', NULL, NULL, 3, 1765251009036, NULL, 0),
  ('69487323d9fdd4cc2d265010', '69462bb67b78013c4213b556', NULL, 'Aks M', 'San Ramon', 'Absolutely felt it!', 1, 3, 0, 1766355747894, NULL, 0),
  ('69487c4e9bc3b8991ab0802c', '69462bb67b78013c4213b556', NULL, 'John C.', 'San Ramon (Windermere)', 'Definitely felt it', 1, 3, 0, 1766358094610, NULL, 0),
  ('69487d8ef890988ec27220a8', '69462bba7b78013c4213b5be', NULL, 'Eduardo', 'Danville', 'My little pup has been sleeping so close to me these past 2-3 weeks, I didn''t realize why until I saw this post', NULL, NULL, 0, 1766358414762, NULL, 0),
  ('69487fa06b079d915bc239f7', '69462bba7b78013c4213b5b8', NULL, 'Priti', 'San Jose', 'I''d love to know how Calaveras fault affects other faults in the Bay Area.', NULL, NULL, 0, 1766358944756, NULL, 0),
  ('6981519a1358e499d11c1f2a', '6981519a1358e499d11c1f29', NULL, 'imran', NULL, 'been on edge since we woke up', NULL, NULL, 0, 1770082714330, NULL, 1),
  ('698152311358e499d11c1f2b', '69462bba7b78013c4213b5c1', NULL, 'idk', NULL, 'we pray', NULL, NULL, 0, 1770082865147, NULL, 0),
  ('698166ec6bedb91d0cb20145', '698166ec6bedb91d0cb20144', NULL, 'john', NULL, 'today was the worst shaking in terms of earthquakes in over my 50 years living in San Ramon', NULL, NULL, 0, 1770088172822, NULL, 1),
  ('69f5252ffc639393a1f27f49', '69462bb67b78013c4213b558', NULL, 'Ellen', '94536', 'A long horizontal separation has occurred (after the San Ramon 4.0+ swarm) between the wall and ceiling at the juncture of two bedrooms, a bathroom and the garage with the main area of my home.', NULL, NULL, 0, 1777673519586, NULL, 0);
